CREATE COLUMN TABLE "TEST_AP"."OLLR" ("AbsEntry" INTEGER CS_INT NOT NULL , "UserSign" SMALLINT CS_INT, "CreateDate" LONGDATE CS_LONGDATE, "CreateTime" SMALLINT CS_INT, "EReportId" INTEGER CS_INT, "Status" NVARCHAR(1) DEFAULT 'C', "Log" NCLOB MEMORY THRESHOLD 1000, "ReportInst" INTEGER CS_INT, "VersionNum" NVARCHAR(13), PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE INDEX "OLLR_REPORT" ON "TEST_AP"."OLLR" ( "EReportId" ASC )